]

for file_path in verification_files:
    # Skip directories
    if file_path.endswith('/'):
        continue

    # Extract the file name and extension
    file_name = file_path.split('/')[-1]
    if '.' in file_name:
        file_name_part, file_extension = file_name.split('.', 1)
    else:
        continue  # Skip files that don't have an extension

    # Split the file name into date and file name parts
    if '__' in file_name_part:
        date_part, file_name_part = file_name_part.split('__', 1)
    else:
        continue  # Skip files that don't match the old format

    # Parse the date part into a datetime object
    try:
        date_obj = datetime.strptime(date_part, "%Y-%b-%d")
    except ValueError:
        continue  # Skip files with invalid date format

    # Format the date as "YYYY-MM-DD"
    new_date_format = date_obj.strftime("%Y-%m-%d")

    # Construct the expected new file name
    expected_new_file_name = f"{file_name_part}/{new_date_format}.{file_extension}"
    expected_new_file_path = f"{os.path.dirname(file_path)}/{expected_new_file_name}"

    # Check if the file exists in the new path
    if os.path.exists(expected_new_file_path):
        print(f"File '{file_name}' has been successfully renamed to '{expected_new_file_name}'")
    else:
        print(f"File '{file_name}' could not be found in the new path '{expected_new_file_path}'")

