    expected_new_file_path = f"{os.path.dirname(file_path)}/{expected_new_file_name}"

    # Check if the file exists in the new path
    if os.path.exists(expected_new_file_path):
        print(f"File '{file_name}' has been successfully renamed to '{expected_new_file_name}'")
    else:
